"use strict";(self.webpackChunksummerz=self.webpackChunksummerz||[]).push([[122545],{653939:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>o,contentTitle:()=>i,default:()=>d,frontMatter:()=>l,metadata:()=>a,toc:()=>c});var r=t(474848),s=t(28453);const l={slug:"2007/11/26",title:"\uc5b4\ucfe0\uc2a4\ud2f1 \ub274\uc2a4 (2007.11.19 ~ 2007.11.25)",date:new Date("2007-11-26T22:50:24.000Z"),authors:"summerz",tags:["media & world","\uc560\ub2c8\uba54\uc774\uc158","\uc0bc\uc131","\uc74c\uc545","\uc0c1\uc2dd","\ubd88\ubc95","\uc815\uce58"]},i=void 0,a={permalink:"/blog/2007/11/26",source:"@site/blog/2007/11/2007-11-26/index.md",title:"\uc5b4\ucfe0\uc2a4\ud2f1 \ub274\uc2a4 (2007.11.19 ~ 2007.11.25)",description:"2007.11.25. \uc560\ub2c8\uba54\uc774\uc158 \uac10\ub3c5 \uc5f0\uc0c1\ud638",date:"2007-11-26T22:50:24.000Z",tags:[{inline:!0,label:"media & world",permalink:"/blog/tags/media-world"},{inline:!0,label:"\uc560\ub2c8\uba54\uc774\uc158",permalink:"/blog/tags/\uc560\ub2c8\uba54\uc774\uc158"},{inline:!0,label:"\uc0bc\uc131",permalink:"/blog/tags/\uc0bc\uc131"},{inline:!0,label:"\uc74c\uc545",permalink:"/blog/tags/\uc74c\uc545"},{inline:!0,label:"\uc0c1\uc2dd",permalink:"/blog/tags/\uc0c1\uc2dd"},{inline:!0,label:"\ubd88\ubc95",permalink:"/blog/tags/\ubd88\ubc95"},{inline:!0,label:"\uc815\uce58",permalink:"/blog/tags/\uc815\uce58"}],readingTime:7.575,hasTruncateMarker:!0,authors:[{name:"summerz",imageURL:"https://github.com/summerz.png",key:"summerz"}],frontMatter:{slug:"2007/11/26",title:"\uc5b4\ucfe0\uc2a4\ud2f1 \ub274\uc2a4 (2007.11.19 ~ 2007.11.25)",date:"2007-11-26T22:50:24.000Z",authors:"summerz",tags:["media & world","\uc560\ub2c8\uba54\uc774\uc158","\uc0bc\uc131","\uc74c\uc545","\uc0c1\uc2dd","\ubd88\ubc95","\uc815\uce58"]},unlisted:!1,prevItem:{title:"\uad6c\uae00 \uc560\ub4dc\uc13c\uc2a4 \ud074\ub9ad\uc601\uc5ed\uc758 \ucd95\uc18c\ub294 \uac1c\uc778 \uac8c\uc2dc\uc790\ubd80\ud130?",permalink:"/blog/2007/11/26-2"},nextItem:{title:"\uc62c\ube14\ub85c\uadf8\uc758 \uae00 \ubaa9\ub85d\uc5d0 \ub9c8\uc6b0\uc2a4\uc624\ubc84 \uc2a4\ud0c0\uc77c \ucd94\uac00",permalink:"/blog/2007/11/22"}},o={authorsImageUrls:[void 0]},c=[];function m(e){const n={a:"a",br:"br",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2007.11.25."})," ",(0,r.jsx)(n.strong,{children:"\uc560\ub2c8\uba54\uc774\uc158 \uac10\ub3c5 \uc5f0\uc0c1\ud638"}),(0,r.jsx)(n.br,{}),"\n\uc560\ub2c8\uba54\uc774\uc158\uc744 \uc81c\uc791\ud558\ub294 \ud55c\uad6d\uc801 \uc0c1\ud669\uc5d0\uc11c \uce7c \ucd9c\uadfc, \uce7c \ud1f4\uadfc\uc744 \uc9c0\ud0a4\ub294 \ub370\uac00 \uc788\uc744\uae4c? \uc774\ub294 \ube44\ub2e8 \ucd9c\ud1f4\uadfc\uc5d0 \ub300\ud55c \uac1c\ub150, \uc2dc\uac04\uc900\uc218\uc5d0 \ub300\ud55c \uac1c\ub150\uc774 \uc544\ub2c8\ub2e4. \ubaa8\ub4e0 \uc791\uc5c5\uc790\ub4e4\uc774 \ucd5c\uc18c\ud55c \uc790\uc2e0\uc758 \uc0b6\uc744 \uc601\uc704\ud558\ub294 \ub370 \ud558\uace0 \uc788\ub294 \uc77c\ub85c \ud558\uc5ec\uae08 \uc601\ud5a5 \ubc1b\uc9c0 \uc54a\uac8c \ud55c\ub2e4\ub294, \uac00\uc7a5 \uae30\ubcf8\uc801\uc778 \ubcf5\uc9c0\uc5d0 \ub300\ud55c \uac1c\ub150\uc774\ub2e4. \uc5ec\uae30\uc5d4 \ubd84\uba85 \uc5f0\uc0c1\ud638 \uac10\ub3c5\uc774 \uace0\uc9d1\uc2a4\ub7fd\uac8c \uc8fc\uc7a5\ud558\ub294 \uc77c\uc5d0 \ub300\ud55c \uad00(\u89c0)\uc774 \ub4dc\ub7ec\ub098\uace0 \uc788\ub2e4. \ub610 \uc774\uc5d0 \ubabb\uc9c0 \uc54a\uac8c \uc911\uc694\ud55c \uac74 \uce7c \ucd9c\uadfc\uacfc \uce7c \ud1f4\uadfc \uc0ac\uc774, \uc989 \uc791\uc5c5\ud560 \uc2dc\uac04 \ub3d9\uc548 \uc791\uc5c5\uc790\ub4e4\uc774 \ub180\uba70, \uc218\ub2e4\ub5a8\uba70 \uc2dc\uac04\uc744 \ud5c8\ube44\ud558\uc9c0 \uc54a\uace0 \uc790\uae30\uac00 \ub9e1\uc740 \uc77c\uc5d0 \ub300\ud574 \ucd5c\uc120\uc744 \ub2e4\ud558\uace0 \uc788\ub2e4\ub294 \uac83\uc774\ub2e4. \uc774\ub294 \ud55c \uc0ac\ub78c\uc774 \uc774\uc0c1\uc801\uc778 \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4e4\uba74 \uadf8 \uc2dc\uc2a4\ud15c\uc744 \uc545\uc6a9\ud558\uc9c0 \uc54a\uace0 \uc81c\ub300\ub85c \uc2dc\uc2a4\ud15c\uc744 \ud65c\uc6a9\ud558\ub294, \uc9c0\uae08\uc758 (\ub098\ub3c4 \uc18d\ud574\uc788\ub294) \uc774 \uc2dc\uc2a4\ud15c\uc740 \uc815\ub9d0\uc774\uc9c0 \uc720\ub840\ub97c \ucc3e\uc544\ubcf4\uae30 \uc5b4\ub835\ub2e4. \ubaa8 \uac10\ub3c5\uc774 \uc774\ub04c\uace0 \uc788\ub294 \ud300\uc740 \ubc24\uc744 \uc0c8\ub294 \uac8c \uc560\ub2c8\uba54\uc774\uc158\uc758 \uc5f4\uc815\uc774\ub77c \uc8fc\uc7a5\ud558\uba70 \uc80a\uc740 \uc2a4\ud0dc\ud504\uc758 \uc5f0\uc560\uc870\ucc28 \uc791\uc5c5\uc744 \ubc29\ud574\ud558\ub294 \ubd88\uc21c\ud55c \uac83\uc73c\ub85c \uc0dd\uac01\ud558\uba70 \ubaa8\ub4e0 \uac8c \uc790\uc2e0\uc758 \ub73b\ub300\ub85c \uc6c0\uc9c1\uc5ec\uc57c \uc88b\uc740 \uc791\ud488\uc774 \ub098\uc628\ub2e4\uace0 \ubbff\uace0 \uc788\ub2e4\uace0 \ud55c\ub2e4. \uadf8\ub807\ub2e4\uba74 \uc5f0\uc0c1\ud638 \uac10\ub3c5\uc774 \uc8fc\uc7a5\ud558\ub294 \uc2dc\uc2a4\ud15c\uc740 \uc544\uc8fc \uc0c1\uc2dd\uc801\uc778 \uac83\uc784\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \ubaa8 \uac10\ub3c5\uc758 \uc2dc\uc2a4\ud15c\uc5d0 \ube44\ud558\uba74 \ucc9c\uad6d\uc758 \uadf8\uac83\uc774\ub2e4. \uc0c1\uc2dd\uc774 \ud1b5\ud558\ub294 \uc0ac\ud68c. \uba4b\uc838\uc694 \uba4b\uc838."]}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.a,{href:"http://www.jumpkarma.com/945",children:"\u25b6 \ubcf4\ub7ec\uac00\uae30"})}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2007.11.22."})," ",(0,r.jsx)(n.strong,{children:'"\uc774\uba85\ubc15 \uc7ac\uc2e0\uc784 \ubb3b\uc790" \uad34\ubb38\uc790 \ud30c\ubb38\u2026\ub0b4\ubd84 \ubd88\uc528\ub418\ub098'}),(0,r.jsx)(n.br,{}),"\n\ud558\ub098\ub294 \uc774\uba85\ubc15 \ub300\uc120\ud6c4\ubcf4\uc758 \uc758\ud639\ub4e4\uc744 \uc5f4\uac70\ud558\uba70 \uc774 \ud6c4\ubcf4\ub97c \uc6d0\uc0c9\uc801\uc73c\ub85c \ube44\ub09c\ud558\ub294 \ub0b4\uc6a9\uc73c\ub85c '\uc704\uc7a5\ucde8\uc5c5, \uc704\uc7a5\uc804\uc785, \uc131\ub9e4\ub9e4, \uc870\uc138\ud3ec\ud0c8\ubc94\uc774 \ub300\ud1b5\ub839\uc774\ub77c\ub2c8 \uac81\ub3c4 \uc5c6\ub098 \uc774\uac8c \ub098\ub77c \uaf34\uc774\ub0d0?'\uace0 \uc801\ud600 \uc788\uc5c8\ub2e4. / \ub2e4\ub978 \uc720\ud615\uc740 \ud55c\ub098\ub77c\ub2f9 \uc804\uad6d\uc704\uc6d0\ud68c\ub97c \uc18c\uc9d1\ud574 \ud6c4\ubcf4\ub97c \uc7ac\uc2e0\uc784\ud574\uc57c \ud55c\ub2e4\ub294 \ub0b4\uc6a9\uc73c\ub85c \ud55c \ub2f9\uc9c1\uc790\uac00 \ubc1b\uc740 \ubb38\uc790\uba54\uc2dc\uc9c0\uc5d0\ub294 '\ubbfc\uc2ec\uc774\ubc18\uc73c\ub85c \uc815\uad8c\uad50\uccb4 \uc704\uae30, \uc804\uad6d\uc704\uc6d0\ud68c \uc18c\uc9d1\ud558\uc5ec \uc7ac\uc2e0\uc784 \ubb3b\uc790'\ub77c\ub294 \ub0b4\uc6a9\uc774 \ub2f4\uaca8\uc788\ub2e4. \uce58\uc5f4\ud55c \ud30c\uc6cc\uac8c\uc784\uc740 \uc544\uc9c1 \ub05d\ub098\uc9c0 \uc54a\uc558\ub2e4?"]}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.a,{href:"http://www.cbs.co.kr/nocut/show.asp?idx=676664",children:"\u25b6 \uae30\uc0ac\ubcf4\uae30"})}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2007.11.20."})," ",(0,r.jsx)(n.strong,{children:"\uc0bc\uc131\uc758 \ub3c4\ub828\ub2d8 \ubd80\uc790 \ub9cc\ub4e4\uae30 \ub9c8\uc220\uc1fc"}),(0,r.jsx)(n.br,{}),"\n\ub9c8\uc220\uc1fc\ub294 1996\ub144 12\uc6d4 \uc815\uc810\uc5d0 \uc774\ub978\ub2e4. \uc774\uc7ac\uc6a9\uc528\ub294 \uc0bc\uc131\uadf8\ub8f9\uc758 \uc9c0\uc8fc\ud68c\uc0ac \uaca9\uc778 \uc0bc\uc131\uc5d0\ubc84\ub79c\ub4dc \uc0ac\ubaa8 \uc804\ud658\uc0ac\ucc44(CB\xb7\uc77c\uc815 \uae30\uac04 \ub4a4 \uc8fc\uc2dd\uc73c\ub85c \uc804\ud658\ud560 \uc218 \uc788\ub294 \ucc44\uad8c) 96\uc5b52\ucc9c\ub9cc\uc6d0\uc5b4\uce58\ub97c \uc0ac\ub4e4\uc778\ub2e4. \uc774\uc7ac\uc6a9\uc528\ub294 \uc5bc\ub9c8 \ub4a4 \uc0bc\uc131\uc5d0\ubc84\ub79c\ub4dc CB\ub97c \uc8fc\uc2dd\uc73c\ub85c \uc804\ud658\ud574 51%\uc758 \uc9c0\ubd84\uc744 \uc7a5\uc545\ud588\ub2e4. \uc0bc\uc131\uadf8\ub8f9\uc758 \u2018\uc2e4\uc81c \uc8fc\uc778\u2019\uc774 \uc774\uac74\ud76c \ud68c\uc7a5\uc5d0\uc11c \uc774\uc7ac\uc6a9\uc528\ub85c \ubc14\ub00c\ub294 \uc21c\uac04\uc774\uc5c8\ub2e4. \uc774\uc0c1\ud55c \uc810\uc740 \uc774\ub54c\uc5d0\ub3c4 \uc774\uc7ac\uc6a9\uc528\ub294 \uad6d\uc678\uc5d0 \uba38\ubb3c\ub7ec \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \u201c\uc774\uc7ac\uc6a9 \uc804\ubb34\uac00 \uc678\uad6d\uc11c \uacf5\ubd80\ub97c \ub9c8\uce58\uace0 \ub3cc\uc544\uc624\ub2c8\uae4c \ub300\ud55c\ubbfc\uad6d \ucd5c\uace0\uc758 \ubd80\uc790\uac00 \ub3fc \uc788\uc5c8\ub2e4\u201d\ub294 \uae40\uc6a9\ucca0 \ubcc0\ud638\uc0ac\uc758 \ubc1c\uc5b8\uc740 \uc774 \ub300\ubaa9\uc744 \uac00\ub9ac\ud0a4\uace0 \uc788\ub2e4. / \ub354\uc6b1 \ubb38\uc81c\uac00 \ub41c \uac74 \ub2f9\uc2dc \uc774\uc7ac\uc6a9\uc528\uac00 \uc778\uc218\ud55c CB\uc758 \uc804\ud658 \uac00\uaca9\uc774 7700\uc6d0\uc774\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \ub098\uc911\uc5d0 \uc0bc\uc131\uc5d0\ubc84\ub79c\ub4dc \uc0ac\uac74 \uc7ac\ud310 \ub54c \ubc95\uc6d0\uc5d0\uc11c \uc778\uc815\ub410\ub4ef \ub2f9\uc2dc \uc138\ubc95\uc0c1 \uac00\uce58\ub294 12\ub9cc7750\uc6d0\uc774\uc5c8\ub2e4. \uc0bc\uc131\uc5d0\ubc84\ub79c\ub4dc \uacbd\uc601\uc9c4\uc774 \ud68c\uc0ac \uc8fc\uc2dd\uc744 \ucd1d\uc218 \uc544\ub4e4\uc5d0\uac8c 17\ubd84\uc758 1\ubc16\uc5d0 \uc548 \ub418\ub294 \u2018\ud5d0\uac12\u2019\uc5d0 \ub118\uaca8\uc900 \uac83\uc774\ub2e4. \ubb3c\ub860, \uc774\uc7ac\uc6a9\uc528\ub294 \ub9c9\ub300\ud55c \uc774\ub4dd\uc744 \uc785\uc5c8\uc9c0\ub9cc, \uadf8 \uc678 \uc0bc\uc131\uc5d0\ubc84\ub79c\ub4dc \uc8fc\uc8fc\ub4e4\uc740 \uadf8\ub9cc\ud07c \ud070 \uc190\uc2e4\uc744 \uc785\uc5c8\ub2e4. \uc8fc\uc8fc\uc758 \uc774\uc775\ubcf4\ub2e4 \ud68c\uc7a5 \uc77c\uac00\uc758 \uc774\uc775\uc744 \ub354 \uc2e0\uacbd\uc4f0\ub294 \uc2e0\uae30\ud55c \ud68c\uc0ac. \uc5b4\ub514 \uc678\uad6d\uc758 '\uc138\uc0c1\uc5d0 \uc774\ub7f0 \uc77c\uc774' \uac19\uc740 \ud504\ub85c\uc5d0 \ub098\uc62c \ubc95\ud55c \ud68c\uc0ac\ub2e4."]}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.a,{href:"http://www.hani.co.kr/section-021005000/2007/11/021005000200711130685047.html",children:"\u25b6 \uae30\uc0ac\ubcf4\uae30"})}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2007.11.19."})," ",(0,r.jsx)(n.strong,{children:"\uc74c\uc545\uc138\uacc4 \ub9c8\uc9c0\ub9c9 \ubc29\uc1a1\uc744 \ub4e3\uace0... (\uc131\uc2dc\uc644)"}),(0,r.jsx)(n.br,{}),'\n*\uc800 \uc131\uc2dc\uc644\uc740 \uc81c\uac00 \uc4f4 \uc544\ub798 \uae00\uc5d0 \ub300\ud574 \ub2e8 \ud55c \uae00\uc790, \ud55c \ubb38\uc7a5\ub3c4 \uac70\uc9d3\uc774 \uc5c6\uc74c\uc744 \uc18c\uc2e0\uc788\uac8c \ubc1d\ud788\uba70, \uc544\ub798\uc758 \uc800\uc758 \uc5b5\uc6b8\ud55c \ud574\uba85\uacfc \uc18c\uacac\uc744 \uc5ec\ub7ec\ubd84\ub4e4\uc774 \uc0c1\uc138\ud788 \uc77d\uc5b4 \ubcf4\uc2dc\uace0, \ub0c9\ucca0\ud788 \ud310\ub2e8\ud558\uc154\uc11c \uac01\uc885 \ud3ec\ud138 \uc0ac\uc774\ud2b8\ub098 \uc74c\uc545 \uc0ac\uc774\ud2b8, \uc74c\uc545 \ub3d9\ud638\ud68c, \ube14\ub85c\uadf8, \uce74\ud398 \ub4f1\uc9c0\uc5d0 \uc62c\ub824 \uc8fc\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4! \uc800\ub294 \ucc2c\uc591\uc77c\uc0c9\uc778 "\uadf8 \ub204\uad6c\ucc98\ub7fc" \uc798 \uc544\ub294 \uae30\uc790\ubd84\ub4e4\ub3c4 \uc5c6\uace0, \uc18c\uc704 \ub9d0\ud558\ub294 \uc5b8\ub860 \ud50c\ub808\uc774\ub77c\ub294 \uac83\ub3c4 \ud560 \uc904 \ubab0\ub77c\uc11c \uc774\ubc88 \ub9cc\ud07c\uc740 \uc5ec\ub7ec\ubd84\ub4e4\uc758 \ub3c4\uc6c0\uc744 \uac04\uc808\ud788 \ubc1b\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \uc774\ubc88\uc5d0 \uacf5\uc601\ubc29\uc1a1 \ud55c \ud504\ub85c\uadf8\ub7a8\uc758 \uc9c4\ud589\uc790\uac00, \uc790\uc2e0\uc758 \ub9c8\uc9c0\ub9c9 \ubc29\uc1a1\uc5d0\uc11c \uc800\ub97c \ube44\ud558\ubc1c\uc5b8\uc744 \ud558\uc600\uae30\uc5d0, \uc774\ub807\uac8c \uc791\uc740 \uc800\ud76c\ud68c\uc0ac \uac8c\uc2dc\ud310\uc5d0\ub9cc \ud574\uba85\ud558\uace0 \ub05d\uce5c\ub2e4\uba74 \ubc14\uc704\uc5d0 \ub2ec\uac40\ub358\uc9c0\uae30 \ubc16\uc5d0 \uc548\ub420 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uac70\ub300\ud55c \uacf5\uc601\ubc29\uc1a1\uc758 \ud798\uc5d0\ub294 \ubabb\ubbf8\uce58\uaca0\uc9c0\ub9cc, \uc5ec\ub7ec\ubd84\ub4e4\uc758 \uc791\uc740\ub3c4\uc6c0\uc774 "\uc815\uc758\ub97c \ubbff\uace0" \uc81c\uac00 \uc55e\uc73c\ub85c \uc0b4\uc544\uac00\ub294\ub370 \ucee4\ub2e4\ub780 "\ud798\uacfc \ud76c\ub9dd"\uc774 \ub420 \uac83\uc774\ub77c \ubbff\uc2b5\ub2c8\ub2e4! \uace0\ub9d9\uc2b5\ub2c8\ub2e4! 2007\ub144 10\uc6d4 17\uc77c \uc0c8\ubcbd 5\uc2dc40\ubd84 \uc131\uc2dc\uc644* \uc804\uc601\ud601, \uc131\uc2dc\uc644\u2026 \uac04\ucca9 \ub9c8\ub0e5 \uc811\uc120\ud558\ub4ef \uc74c\uc545\uc744 \ub4e4\uc5c8\ub358 \uc0ac\ub78c\ub4e4\uc5d0\uac8c\ub294 \uc18c\uc911\ud55c \uc774\ub984\uc778\ub370 \ucc38 \uc544\uc27d\ub2e4. \uadf8\ub098\uc800\ub098 \uc131\uc2dc\uc644\uc774 \uc800\ub807\uac8c \ubd84\ud574\ud558\uba70 \uc774\uc57c\uae30\ud558\ub294\ub370\ub3c4 \uc804\uc601\ud601\uc740 \uc65c \uc544\ubb34 \ub9d0\ub3c4 \ud558\uc9c0 \uc54a\uace0 \uc788\uc744\uae4c.']}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.a,{href:"http://www.siwan.co.kr/community/board_view.asp?db=board_&num=473&page=1&ftype=&ftext=",children:"\u25b6 \ubcf4\ub7ec\uac00\uae30"})})]})}function d(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(m,{...e})}):m(e)}},28453:(e,n,t)=>{t.d(n,{R:()=>i,x:()=>a});var r=t(296540);const s={},l=r.createContext(s);function i(e){const n=r.useContext(l);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),r.createElement(l.Provider,{value:n},e.children)}}}]);